<script setup lang="ts">
import {ref,onMounted} from 'vue'
const props=defineProps<{request:(path:string,body?:any,method?:string)=>Promise<any>}>()
const date=new Date(),to=ref(date.toISOString().slice(0,10)),from=ref(new Date(date.getTime()-29*86400000).toISOString().slice(0,10)),page=ref(1),result=ref<any>(null),busy=ref(false),error=ref('')
const labels:Record<string,string>={visits:'Visites réservées',prospects:'Prospects distincts',cancelled:'Annulées',upcoming:'À venir',reported:'Résultats renseignés',performed:'Effectuées (Oui)',not_performed:'Non effectuées (Non)',results_due:'Résultats manquants',interested:'Intéressés',not_interested:'Non intéressés',follow_up:'Suivi nécessaire',performed_rate:'Taux effectué (%)',interest_rate:'Taux d’intérêt parmi les visites effectuées (%)'}
async function load(){busy.value=true;error.value='';try{result.value=await props.request(`workspace-statistics/?from=${from.value}&to=${to.value}&page=${page.value}`)}catch(e:any){error.value=e.message;result.value=null}finally{busy.value=false}}
onMounted(load)
</script>
<template><section><h3>Statistiques des visites Isolation</h3><p v-if="error" role="alert">{{error}}</p><form @submit.prevent="page=1;load()"><label>Du (UTC)<input v-model="from" type="date" required></label><label>Au inclus (UTC)<input v-model="to" type="date" required></label><button class="primary" :disabled="busy">Calculer</button></form><template v-if="result"><p>{{result.definition}}</p><small>Calculé le {{new Date(result.as_of).toLocaleString('fr-FR')}}. Un report peut déplacer une visite dans une autre période.</small><dl><template v-for="(label,key) in labels" :key="key"><dt>{{label}}</dt><dd>{{result.totals[key]===null?'Non calculable':result.totals[key]}}</dd></template></dl><template v-if="result.setters"><h4>Par setter d’origine</h4><article v-for="row in result.setters.results" :key="row.setter_id"><h5>{{row.setter_name}} ({{row.setter_id}})</h5><dl><template v-for="(label,key) in labels" :key="key"><dt>{{label}}</dt><dd>{{row[key]===null?'Non calculable':row[key]}}</dd></template></dl></article><p>{{result.setters.count}} setter(s) · page {{page}}</p><button class="secondary" :disabled="busy||!result.setters.previous" @click="page--;load()">Précédent</button><button class="secondary" :disabled="busy||!result.setters.next" @click="page++;load()">Suivant</button></template></template><p>Les appels Phonetico, ventes, contrats et exports statistiques ne sont pas inclus.</p></section></template>
